#include <bits/stdc++.h>
using namespace std;const int N=12,M=50;int a[M],b[M],q[N],c[N];double w[M],d[N],W[N][N],r;bool z[N],v[N];int n,e;bool C(double x){fill(d,d+n,0);fill(c,c+n,0);fill(z,z+n,1);int l=0,R=n;for(int i=0;i<n;i++)q[i]=i;while(l<R){int u=q[l++%N];z[u]=0;for(int i=0;i<e;i++)if(a[i]==u&&d[b[i]]>d[u]+w[i]-x+1e-11){d[b[i]]=d[u]+w[i]-x;c[b[i]]=c[u]+1;if(c[b[i]]>=n)return 1;if(!z[b[i]])z[b[i]]=1,q[R++%N]=b[i];}}return 0;}void D(int s,int x,int k,double y){v[x]=1;for(int i=0;i<n;i++)if(W[x][i]<1e90){if(i==s)r=min(r,(y+W[x][i])/(k+1));else if(!v[i])D(s,i,k+1,y+W[x][i]);}v[x]=0;}int main(int Cc,char**V){ios::sync_with_stdio(0);cin.tie(0);int R=Cc>1?stoi(V[1]):1000;unsigned long long S=Cc>2?stoull(V[2]):1;mt19937_64 g(S);while(R--){n=g()%6+2;e=0;for(int i=0;i<n;i++)for(int j=0;j<n;j++)W[i][j]=1e100;for(int i=0;i<n;i++){int A=g()%11,B=g()%11,F=g()%21;a[e]=i;b[e]=i+1==n?0:i+1;w[e]=B+F;W[a[e]][b[e]]=min(W[a[e]][b[e]],w[e]);e++;a[e]=i+1==n?0:i+1;b[e]=i;w[e]=A-F;W[a[e]][b[e]]=min(W[a[e]][b[e]],w[e]);e++;}double l=-30,h=30;for(int i=0;i<65;i++){double x=(l+h)/2;if(C(x))h=x;else l=x;}r=1e100;for(int i=0;i<n;i++)D(i,i,0,0);if(abs(h-r)>1e-7)return cout<<"WA\n",1;}cout<<"OK\n";}
